(function() {
    'use strict';

    class FinStatementAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'FinStatement Builder';
            this.version = '1.1.0';
            this._lastRenderedPeriod = 0;
            this._wired = false;
            this.ROUNDS = [
                { answers: [50000, 37000, 26000] },
                { answers: [38000, 36000, 34000] },
                { answers: [600, 16000, 2800] },
                { answers: [8400, 28400, 13000] }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    correctCount: 0,
                    totalQuestions: 0,
                    accuracyText: '0%',
                    correctText: '0/0',
                    scoreHistory: [],
                    roundCorrectHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    input1: 0,
                    input2: 0,
                    input3: 0
                };
            }
            this._renderRound(state.currentPeriod || 1);
        }

        validateDecisions(decisions) {
            var el1 = document.getElementById('input1');
            var el2 = document.getElementById('input2');
            var el3 = document.getElementById('input3');
            if (el1) decisions.input1 = parseFloat(el1.value) || 0;
            if (el2) decisions.input2 = parseFloat(el2.value) || 0;
            if (el3) decisions.input3 = parseFloat(el3.value) || 0;

            if (decisions.input1 === 0 && decisions.input2 === 0 && decisions.input3 === 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var answers = [d.input1, d.input2, d.input3];
            var correct = 0;
            var roundScore = 0;
            var feedbackLines = [];
            var roundNum = state.currentPeriod;
            var prefix = 'r' + roundNum + '_';
            var t = window.mySimulation.t.bind(window.mySimulation);

            for (var i = 0; i < 3; i++) {
                var userAns = answers[i];
                var correctAns = round.answers[i];
                var label = t(prefix + 'label' + (i + 1));
                var diff = Math.abs(userAns - correctAns);

                if (diff === 0) {
                    correct++;
                    roundScore += 100;
                    feedbackLines.push('<b>' + label + ':</b> ' + t('correct_text') + ' ($' + correctAns.toLocaleString() + ')');
                } else if (diff <= Math.abs(correctAns * 0.05)) {
                    roundScore += 50;
                    feedbackLines.push('<b>' + label + ':</b> ' + t('close_text') + ' $' + correctAns.toLocaleString());
                } else {
                    feedbackLines.push('<b>' + label + ':</b> ' + t('incorrect_text') + ' $' + correctAns.toLocaleString());
                }
            }

            state.domainState.score += roundScore;
            state.domainState.correctCount += correct;
            state.domainState.totalQuestions += 3;
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.roundCorrectHistory.push(correct);

            var totalQ = state.domainState.totalQuestions;
            var totalC = state.domainState.correctCount;
            state.domainState.accuracyText = (totalQ > 0 ? Math.round((totalC / totalQ) * 100) : 0) + '%';
            state.domainState.correctText = totalC + '/' + totalQ;

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackPanel.style.display = 'block';
                var cls = correct === 3 ? 'finsim-good' : correct >= 2 ? 'finsim-partial' : 'finsim-poor';
                feedbackPanel.className = 'finsim-feedback ' + cls;
                feedbackText.innerHTML = '<b>' + t('round_results') + ' ' + roundScore + ' pts (' + correct + '/3)</b><br>' + feedbackLines.join('<br>');
            }

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                correct: correct,
                totalScore: state.domainState.score
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score', (v) => v + ' pts');
            uiManager.bind('accuracyDisplay', 'domainState.accuracyText');
            uiManager.bind('correctDisplay', 'domainState.correctText');
            this._wireFrameworkEvents();
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: [
                                'rgba(26,82,118,0.7)',
                                'rgba(41,128,185,0.7)',
                                'rgba(39,174,96,0.7)',
                                'rgba(243,156,18,0.7)'
                            ],
                            borderColor: ['#1a5276', '#2980b9', '#27ae60', '#f39c12'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score by Round' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 300, title: { display: true, text: 'Points' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            var n = history ? history.length : 0;
            if (!n) return { totalPeriods: 0 };
            var totalScore = 0;
            var totalCorrect = 0;
            for (var i = 0; i < n; i++) {
                var r = history[i].results;
                if (r) {
                    totalScore += r.roundScore || 0;
                    totalCorrect += r.correct || 0;
                }
            }
            var maxScore = n * 300;
            var totalQuestions = n * 3;
            var pct = maxScore > 0 ? Math.round((totalScore / maxScore) * 100) : 0;

            var perfKey = pct >= 85 ? 'perf_excellent'
                        : pct >= 65 ? 'perf_good'
                        : pct >= 45 ? 'perf_developing'
                        : 'perf_needs';
            var insightKey = totalCorrect >= 10 ? 'insight_strong'
                           : totalCorrect >= 7  ? 'insight_good'
                           : 'insight_focus';

            return {
                totalPeriods: n,
                totalScore: totalScore,
                maxScore: maxScore,
                totalCorrect: totalCorrect,
                totalQuestions: totalQuestions,
                accuracyPct: pct,
                accuracy: pct + '%',
                performance: t(perfKey),
                insights: [t(insightKey)],
                message: t(perfKey)
            };
        }

        getHint(state, results) {
            if (!results || results.correct >= 2) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var roundNum = Math.min(state.currentPeriod || 1, 4);
            return t('hint_r' + roundNum);
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score', formatter: (v) => v + ' pts' },
                { key: 'results.correct', label: 'Correct', i18nKey: 'col_correct', formatter: (v) => v + '/3' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:            `FinStatement Builder`,
                    subtitle:         `From Transactions to Financial Statements`,
                    round_label:      `Round`,
                    period_of:        `of`,
                    score_label:      `Score`,
                    accuracy_label:   `Accuracy`,
                    correct_label:    `Correct`,
                    answers_heading:  `Your Answers`,
                    submit_btn:       `Submit Round`,
                    undo_btn:         `Undo Last Round`,
                    input_warning:    `Please enter your answers before submitting`,
                    correct_text:     `Correct!`,
                    close_text:       `Close! Correct answer:`,
                    incorrect_text:   `Incorrect. Correct answer:`,
                    round_results:    `Round Results:`,
                    col_score:        `Score`,
                    col_correct:      `Correct`,
                    summary_title:      `Simulation Complete`,
                    summary_score:      `Total Score`,
                    summary_accuracy:   `Accuracy`,
                    summary_correct:    `Correct Answers`,
                    summary_perf:       `Performance`,
                    perf_excellent:     `Excellent`,
                    perf_good:          `Good`,
                    perf_developing:    `Developing`,
                    perf_needs:         `Needs Practice`,
                    insight_strong:     `Strong command of the full accounting cycle \u2014 you can read and build financial statements with confidence.`,
                    insight_good:       `Good foundations in accounting mechanics. Review the rounds where you lost points to sharpen your understanding.`,
                    insight_focus:      `Focus on the accounting equation (Assets = Liabilities + Equity) and how each transaction affects at least two accounts.`,
                    summary_reconcile:  `Key insight: profit and cash change are different numbers. Net income was $8,400 while cash rose $13,000 \u2014 the gap is explained by non-cash adjustments and the vehicle purchase.`,
                    r1_label1:        `Ending Cash ($)`,
                    r1_label2:        `Ending Accounts Receivable ($)`,
                    r1_label3:        `Total Cost of Goods Sold ($)`,
                    r2_label1:        `Ending Cash ($)`,
                    r2_label2:        `Delivery Vehicle Value ($)`,
                    r2_label3:        `Total Bank Loan Balance ($)`,
                    r3_label1:        `Depreciation Expense ($)`,
                    r3_label2:        `Total Wages Expense ($)`,
                    r3_label3:        `Income Tax Expense ($)`,
                    r4_label1:        `Net Income ($)`,
                    r4_label2:        `Ending Retained Earnings ($)`,
                    r4_label3:        `Net Change in Cash ($)`,
                    hint_r1:          `Remember: cash sales increase Cash directly, credit sales increase Accounts Receivable. COGS reduces Inventory when goods are delivered.`,
                    hint_r2:          `The vehicle is an asset (not an expense). The loan increases both the asset and the liability. Cash only decreases by the cash portion paid.`,
                    hint_r3:          `None of these adjustments involve cash. Compute pre-tax income by subtracting ALL expenses from revenue, then apply the 25% tax rate.`,
                    hint_r4:          `Net Income = Revenue minus All Expenses (including tax). Cash changed due to both operating flows AND the vehicle purchase. Opening Cash was $25,000.`,
                    briefing_r1:      `<h4>Round 1: Operating Transactions</h4><p><b>Opening Balances &mdash; Mercado Fresco S.A., October 1:</b></p><table class="table table-sm table-bordered"><tr><td>Cash</td><td style="text-align:right">$25,000</td><td>Accounts Payable</td><td style="text-align:right">$10,000</td></tr><tr><td>Accounts Receivable</td><td style="text-align:right">$20,000</td><td>Accrued Wages</td><td style="text-align:right">$3,000</td></tr><tr><td>Inventory</td><td style="text-align:right">$16,000</td><td>Bank Loan</td><td style="text-align:right">$10,000</td></tr><tr><td>Prepaid Insurance</td><td style="text-align:right">$2,400</td><td>Share Capital</td><td style="text-align:right">$20,000</td></tr><tr><td>Allow. Doubtful Accts</td><td style="text-align:right">($400)</td><td>Retained Earnings</td><td style="text-align:right">$20,000</td></tr><tr><td><b>Total Assets</b></td><td style="text-align:right"><b>$63,000</b></td><td><b>Total L + E</b></td><td style="text-align:right"><b>$63,000</b></td></tr></table><hr><p><b>Process these transactions:</b></p><ol><li>Cash sale of produce to Restaurant La Taberna: <b>$15,000</b></li><li>Credit sale to Supermarket Verde (net 30 days): <b>$35,000</b></li><li>Inventory purchased on credit from Finca Organica: <b>$25,000</b></li><li>Cost of goods sold for sales #1 and #2: <b>$26,000</b></li><li>Collected from prior accounts receivable: <b>$18,000</b></li><li>Paid suppliers from opening accounts payable: <b>$8,000</b></li></ol><p><em>Calculate the correct ending balances after recording all six transactions.</em></p>`,
                    briefing_r2:      `<h4>Round 2: Wages, Assets and Financing</h4><p><b>Correct balances after Round 1:</b></p><table class="table table-sm table-bordered"><tr><td>Cash</td><td style="text-align:right">$50,000</td><td>AP</td><td style="text-align:right">$27,000</td></tr><tr><td>AR</td><td style="text-align:right">$37,000</td><td>Revenue (cumul.)</td><td style="text-align:right">$50,000</td></tr><tr><td>Inventory</td><td style="text-align:right">$15,000</td><td>COGS (cumul.)</td><td style="text-align:right">$26,000</td></tr></table><hr><p><b>New transactions:</b></p><ol><li>Paid wages for first half of October: <b>$8,000</b></li><li>Utilities expense accrued (not yet paid): <b>$500</b></li><li>Purchased refrigerated delivery vehicle: <b>$36,000</b> &mdash; paid <b>$12,000</b> cash, financed <b>$24,000</b> with bank loan</li><li>Interest accrual on new loan: $24,000 &times; 8% / 12 = <b>$160</b></li><li>Advance rent payment for Nov&ndash;Dec: <b>$2,000</b></li><li>Cash sale: <b>$10,000</b> | COGS: <b>$5,000</b></li></ol><p><em>Enter the correct values below.</em></p>`,
                    briefing_r3:      `<h4>Round 3: Period-End Adjustments</h4><p><b>Correct position after Round 2:</b></p><table class="table table-sm table-bordered"><tr><td>Cash</td><td style="text-align:right">$38,000</td><td>Revenue</td><td style="text-align:right">$60,000</td></tr><tr><td>AR</td><td style="text-align:right">$37,000</td><td>COGS</td><td style="text-align:right">$31,000</td></tr><tr><td>Inventory</td><td style="text-align:right">$10,000</td><td>Wages Exp</td><td style="text-align:right">$8,000</td></tr><tr><td>Vehicles</td><td style="text-align:right">$36,000</td><td>Utilities Exp</td><td style="text-align:right">$500</td></tr><tr><td>Prepaid Ins</td><td style="text-align:right">$2,400</td><td>Interest Exp</td><td style="text-align:right">$160</td></tr></table><hr><p><b>All five adjustments below are non-cash entries:</b></p><ol><li>Depreciation on delivery vehicle: $36,000 / 60 months</li><li>Insurance consumed: $2,400 / 12 months = <b>$200</b></li><li>Accrued wages (second half of October): <b>$8,000</b></li><li>Bad debt provision: 2% of AR ($37,000) = $740; minus existing $400 = <b>$340</b></li><li>Income tax provision at <b>25%</b> of pre-tax income</li></ol><p><em>You must compute pre-tax income to determine the tax. Add ALL expenses (including adjustments above) before calculating.</em></p>`,
                    briefing_r4:      `<h4>Round 4: Closing Entries and Reconciliation</h4><p><b>Complete expense summary after all adjustments:</b></p><table class="table table-sm table-bordered"><tr><td>Revenue</td><td style="text-align:right">$60,000</td><td>Wages</td><td style="text-align:right">$16,000</td></tr><tr><td>COGS</td><td style="text-align:right">$31,000</td><td>Utilities</td><td style="text-align:right">$500</td></tr><tr><td>Depreciation</td><td style="text-align:right">$600</td><td>Interest</td><td style="text-align:right">$160</td></tr><tr><td>Insurance</td><td style="text-align:right">$200</td><td>Bad Debt</td><td style="text-align:right">$340</td></tr><tr><td>Income Tax</td><td style="text-align:right">$2,800</td><td></td><td></td></tr></table><hr><p><b>Closing process:</b> Close all revenue and expense accounts to Income Summary, then close Income Summary to Retained Earnings.</p><p><b>The Reconciliation Challenge:</b> The company made a profit this month, but how much did cash actually change? The two numbers are different &mdash; understanding why is the key insight of this simulation.</p><p><em>Opening Cash: $25,000 | Ending Cash: $38,000 | Opening Retained Earnings: $20,000</em></p>`
                },
                es: {
                    title:            `Constructor de Estados Financieros`,
                    subtitle:         `De Transacciones a Estados Financieros`,
                    round_label:      `Ronda`,
                    period_of:        `de`,
                    score_label:      `Puntaje`,
                    accuracy_label:   `Exactitud`,
                    correct_label:    `Correctas`,
                    answers_heading:  `Tus Respuestas`,
                    submit_btn:       `Enviar Ronda`,
                    undo_btn:         `Deshacer Ronda`,
                    input_warning:    `Ingresa tus respuestas antes de enviar`,
                    correct_text:     `¡Correcto!`,
                    close_text:       `¡Cerca! Respuesta correcta:`,
                    incorrect_text:   `Incorrecto. Respuesta correcta:`,
                    round_results:    `Resultados de la Ronda:`,
                    col_score:        `Puntaje`,
                    col_correct:      `Correctas`,
                    summary_title:      `Simulación Completada`,
                    summary_score:      `Puntaje Total`,
                    summary_accuracy:   `Exactitud`,
                    summary_correct:    `Respuestas Correctas`,
                    summary_perf:       `Desempeño`,
                    perf_excellent:     `Excelente`,
                    perf_good:          `Bien`,
                    perf_developing:    `En Desarrollo`,
                    perf_needs:         `Necesita Práctica`,
                    insight_strong:     `Dominio sólido del ciclo contable completo: puedes leer y construir estados financieros con confianza.`,
                    insight_good:       `Buenas bases en la mecánica contable. Revisa las rondas donde perdiste puntos para afianzar tu comprensión.`,
                    insight_focus:      `Enfócate en la ecuación contable (Activos = Pasivos + Patrimonio) y en cómo cada transacción afecta al menos dos cuentas.`,
                    summary_reconcile:  `Idea clave: la utilidad y el cambio en efectivo son cifras distintas. La utilidad neta fue $8,400 mientras el efectivo aumentó $13,000; la diferencia se explica por los ajustes sin efectivo y la compra del vehículo.`,
                    r1_label1:        `Efectivo Final ($)`,
                    r1_label2:        `Cuentas por Cobrar Final ($)`,
                    r1_label3:        `Costo de Ventas Total ($)`,
                    r2_label1:        `Efectivo Final ($)`,
                    r2_label2:        `Valor del Vehículo ($)`,
                    r2_label3:        `Saldo Total Préstamo Bancario ($)`,
                    r3_label1:        `Gasto de Depreciación ($)`,
                    r3_label2:        `Gasto Total de Salarios ($)`,
                    r3_label3:        `Gasto de Impuesto a la Renta ($)`,
                    r4_label1:        `Utilidad Neta ($)`,
                    r4_label2:        `Utilidades Retenidas Final ($)`,
