        _renderRound(periodNum) {
            var roundNum = Math.min(Math.max(periodNum || 1, 1), this.ROUNDS.length);
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = t('briefing_r' + roundNum);
            }

            var prefix = 'r' + roundNum + '_';
            for (var i = 1; i <= 3; i++) {
                var labelEl = document.getElementById('label' + i);
                if (labelEl) {
                    var key = prefix + 'label' + i;
                    labelEl.textContent = t(key);
                    labelEl.setAttribute('data-i18n', key);
                }
            }

            for (var j = 1; j <= 3; j++) {
                var inputEl = document.getElementById('input' + j);
                if (inputEl && !inputEl.disabled) inputEl.value = '0';
            }

            this._lastRenderedPeriod = roundNum;
        }

        _hideFeedback() {
            var fp = document.getElementById('feedbackPanel');
            if (fp) fp.style.display = 'none';
        }

        _wireFrameworkEvents() {
            if (this._wired) return;
            var sim = window.mySimulation;
            if (!sim || !sim.eventBus) return;
            var self = this;
            sim.eventBus.on('period:submitted', function() { self._onPeriodSubmitted(); });
            sim.eventBus.on('period:undone', function() { self._onPeriodUndone(); });
            document.addEventListener('express:langchanged', function() {
                try {
                    var live = (window.mySimulation && window.mySimulation.state)
                        ? window.mySimulation.state.currentPeriod : 1;
                    self._lastRenderedPeriod = 0;
                    self._renderRound(live);
                } catch (e) {}
            });
            this._wired = true;
        }

        _onPeriodSubmitted() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var live = sim.state.currentPeriod;
            // The framework advances currentPeriod AFTER grading. Render the new round
            // (briefing, labels, cleared inputs) but keep the feedback panel visible so
            // the player can still read the result of the round they just submitted.
            if (typeof live === 'number' && live > this._lastRenderedPeriod && live <= this.ROUNDS.length) {
                this._renderRound(live);
            }
        }

        _onPeriodUndone() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            // Undoing the first round empties history; the framework's initialize()
            // guard will NOT reset a non-empty domainState, so reset it here to keep
            // the score/accuracy displays consistent with an empty history.
            if (!sim.state.history || sim.state.history.length === 0) {
                sim.state.domainState = {
                    score: 0,
                    correctCount: 0,
                    totalQuestions: 0,
                    accuracyText: '0%',
                    correctText: '0/0',
                    scoreHistory: [],
                    roundCorrectHistory: []
                };
                try { sim.updateUI(); } catch (e) {}
            }
            this._hideFeedback();
            this._lastRenderedPeriod = 0;
            this._renderRound(sim.state.currentPeriod || 1);
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            var s = summary || {};
            var score = (s.totalScore != null ? s.totalScore : 0);
            var maxScore = (s.maxScore != null ? s.maxScore : 1200);
            var correct = (s.totalCorrect != null ? s.totalCorrect : 0);
            var totalQ = (s.totalQuestions != null ? s.totalQuestions : 12);
            var acc = (s.accuracyPct != null ? s.accuracyPct : 0);
            var perf = s.performance || '';
            var insight = (s.insights && s.insights.length) ? s.insights[0] : '';
            var row = function(label, value) {
                return '<div style="display:flex;justify-content:space-between;padding:6px 2px;border-bottom:1px solid #e9ecef;">' +
                    '<span style="color:#6c757d;">' + label + '</span>' +
                    '<span style="font-weight:700;color:#1a5276;">' + value + '</span></div>';
            };
            return '<div style="padding:8px 4px;text-align:left;max-width:420px;margin:0 auto;">' +
                '<h4 style="text-align:center;color:#1a5276;margin:0 0 16px;">' + t('summary_title') + '</h4>' +
                row(t('summary_score'), score + ' / ' + maxScore + ' pts') +
                row(t('summary_correct'), correct + ' / ' + totalQ) +
                row(t('summary_accuracy'), acc + '%') +
                row(t('summary_perf'), '<b>' + perf + '</b>') +
                '<p style="margin:16px 0 8px;line-height:1.55;">' + insight + '</p>' +
                '<p style="margin:0;font-size:0.9rem;color:#555;line-height:1.55;"><em>' + t('summary_reconcile') + '</em></p>' +
                '</div>';
        }
    }

